import boto3
from typing import Dict

def extract_form_key_values(file_path: str) -> Dict[str, str]:
    textract = boto3.client('textract')
    with open(file_path, 'rb') as f:
        doc_bytes = f.read()

    response = textract.analyze_document(
        Document={'Bytes': doc_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']
    block_map = {b['Id']: b for b in blocks}
    kv_pairs = {}

    def extract_text(block):
        words = []
        for rel in block.get('Relationships', []):
            if rel['Type'] == 'CHILD':
                for cid in rel['Ids']:
                    child = block_map.get(cid)
                    if child and child.get('BlockType') == 'WORD':
                        words.append(child['Text'])
        return ' '.join(words)

    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block.get('EntityTypes', []):
            key_text = extract_text(block)
            value_text = ''
            for rel in block.get('Relationships', []):
                if rel['Type'] == 'VALUE':
                    for vid in rel['Ids']:
                        val_block = block_map.get(vid)
                        if val_block and val_block['BlockType'] == 'KEY_VALUE_SET' and 'VALUE' in val_block.get('EntityTypes', []):
                            value_text = extract_text(val_block)
                            break
                    break
            if key_text:
                kv_pairs[key_text] = value_text

    return kv_pairs
